
const simplifyRegex = /[^A-Z0-9]+/gi;

/**
 * Normalises a string into a simplified, comparison-friendly form by
 * lower-casing it and stripping every character that is not a letter or digit
 * (spaces, punctuation, symbols, etc.).
 *
 * Useful for loose, case- and formatting-insensitive comparisons where only the
 * alphanumeric content matters.
 *
 * @param value - The string to simplify.
 * @returns The lower-cased string with all non-alphanumeric characters removed.
 *
 * @example
 * ```ts
 * simplifyString('Hello, World!'); // 'helloworld'
 * simplifyString('Game #123');     // 'game123'
 * ```
 */
export function simplifyString(value: string) {
    return value.toLowerCase().replace(simplifyRegex, '');
}